import hashlib
import os
from collections import defaultdict

def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    hashes = defaultdict(list)
    for root, _, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash is not None:
                # Get relative path and normalize to use '/'
                rel_path = os.path.relpath(filepath, root_dir).replace('\\', '/')
                hashes[file_hash].append(rel_path)

    duplicates = []
    for group in hashes.values():
        if len(group) > 1:
            duplicates.append(sorted(group))

    return duplicates

root_dir = 'dosyalar'
if os.path.exists(root_dir):
    duplicate_groups = find_duplicates(root_dir)
    # Sort groups by their first element (alphabetically)
    duplicate_groups.sort(key=lambda x: x[0])

    with open('kopyalar.txt', 'w', encoding='utf-8') as f:
        for group in duplicate_groups:
            f.write(" | ".join(group) + "\n")
    print(f"Bulunan grup sayısı: {len(duplicate_groups)}")
else:
    print("Hata: 'dosyalar' klasörü bulunamadı.")

