def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_and_save_duplicates(root_dir, output_file):
    hashes = defaultdict(list)
    for root, _, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash is not None:
                rel_path = os.path.relpath(filepath, root_dir).replace('\\', '/')
                hashes[file_hash].append(rel_path)

    duplicate_groups = []
    for group in hashes.values():
        if len(group) > 1:
            duplicate_groups.append(sorted(group))

    if not duplicate_groups:
        return 0

    # Grupları ilk elemanlarına göre alfabetik sırala
    duplicate_groups.sort(key=lambda x: x[0])

    with open(output_file, 'w', encoding='utf-8') as f:
        for group in duplicate_groups:
            f.write(" | ".join(group) + "\n")

    return len(duplicate_groups)

if __name__ == "__main__":
    root = 'dosyalar'
    output = 'kopyalar.txt'
    count = find_and_save_duplicates(root, output)
    print(f"Success: Found {count} duplicate groups and saved to {output}")

